//! Model retirements: which provider model IDs are shut down or scheduled to
//! be, what each provider lists as the replacement, and which call parameters
//! have to change with the model.
//!
//! The facts come from the providers' own deprecation pages (OpenAI,
//! Anthropic, the Gemini API and Gemini on Google Cloud), by way of Arbor's
//! retirement recipes, and are bundled at build time from
//! `data/model-retirements.json`. That file is generated by
//! `scripts/retirements/generate_model_retirements.py`; never edit it by
//! hand. The tests below recompute its digest, so a hand edit fails
//! `cargo test`, and the generator's `--check` mode fails when the recipes
//! have moved on.
//!
//! [`check`] matches the model values that [`crate::usages`] found at SDK
//! calls against this data. Nothing here reads files, runs code or reaches
//! the network.

mod base_url;
mod check;
mod date;
mod gaps;

pub use base_url::BaseUrl;
pub use check::{
    check, python_literal, CallKind, ChainStep, Change, ChangeKind, CheckOptions, Confidence,
    DataInfo, Decision, DecisionOption, Finding, FixKind, MatchKind, NextShutdown, OptionEffect,
    ParamValue, ProviderDate, RecipeRef, ReportOptions, RetirementReport, ReviewItem, RoutingClass,
    ScanInput, State, Summary, UncheckedArgs, Unreadable, FINE_TUNING, REPORT_VERSION,
};
pub use date::Date;
pub use gaps::{gap_text, routing_gap_text, value_gap_text, GAP_REASONS};

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::OnceLock;

/// The bundled data file.
pub const DATA_JSON: &str = include_str!("../../data/model-retirements.json");

/// Version of the data file's shape.
pub const DATA_SCHEMA: u32 = 1;

/// A provider endpoint with its own retirement schedule.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Table {
    /// The OpenAI API (`api.openai.com`).
    Openai,
    /// Anthropic-operated platforms (the Claude API).
    Anthropic,
    /// The Gemini Developer API (`generativelanguage.googleapis.com`).
    GeminiApi,
    /// Gemini on Google Cloud (Vertex AI, now Gemini Enterprise Agent Platform).
    Vertex,
}

impl Table {
    pub const ALL: [Table; 4] = [
        Table::Openai,
        Table::Anthropic,
        Table::GeminiApi,
        Table::Vertex,
    ];

    /// The snake_case name used in JSON.
    pub fn as_str(self) -> &'static str {
        match self {
            Table::Openai => "openai",
            Table::Anthropic => "anthropic",
            Table::GeminiApi => "gemini_api",
            Table::Vertex => "vertex",
        }
    }

    /// Who sets the schedule, as people say it.
    pub fn provider(self) -> &'static str {
        match self {
            Table::Openai => "OpenAI",
            Table::Anthropic => "Anthropic",
            Table::GeminiApi => "Google",
            Table::Vertex => "Google Cloud",
        }
    }
}

impl std::fmt::Display for Table {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

/// How firm a listed date is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DateKind {
    /// The model stops working on that date (OpenAI, Anthropic).
    Hard,
    /// The earliest the model may stop working (Gemini API, Google Cloud).
    Earliest,
}

/// What the provider says about a model ID, as of the data date.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EntryStatus {
    /// Shut down: the provider says so, or the API already answers 404.
    ShutDown,
    /// Scheduled to shut down on `date`.
    Retiring,
    /// Deprecated with no shutdown date announced.
    Deprecated,
    /// Probably shut down or retiring, but no provider page says so for this
    /// exact ID (an alias, a spelling variant, a past "earliest" date).
    Unconfirmed,
    /// The provider routes requests for this ID to a newer model.
    AutoRouted,
}

/// How a fact was established.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Verified {
    /// A live API call (`verified_on`).
    Live,
    /// Stated on the provider's documentation.
    Docs,
    /// Not stated for this case; reported so people can check.
    Unverified,
}

/// Whether Arbor's recipe would swap the model string automatically.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Action {
    Rewrite,
    ReportOnly,
}

/// A recipe the data was built from.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RecipeInfo {
    pub id: String,
    pub version: String,
    pub file: String,
    /// SHA-256 of the recipe file the data was generated from.
    pub sha256: String,
    pub table: Table,
    pub provider: String,
    pub date_kind: DateKind,
    pub retrieved_on: String,
    /// The provider pages the recipe was built from; the first is the
    /// deprecations page.
    pub source_urls: Vec<String>,
}

/// One model ID on one provider endpoint.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ModelEntry {
    pub model: String,
    pub table: Table,
    pub recipe: String,
    pub status: EntryStatus,
    /// `YYYY-MM-DD`: the shutdown (or earliest shutdown) date.
    #[serde(default)]
    pub date: Option<String>,
    /// The single replacement the provider lists.
    #[serde(default)]
    pub replacement: Option<String>,
    /// The provider's replacement cell when it lists several, none, or adds
    /// a parameter (`gpt-5.6-sol (reasoning.mode: pro)`).
    #[serde(default)]
    pub replacement_text: Option<String>,
    pub action: Action,
    /// The recipe whose parameter rules apply to calls of this model.
    #[serde(default)]
    pub rule_set: Option<String>,
    /// `non_reasoning`, `reasoning`, `reasoning_pro`, `image`...
    #[serde(default)]
    pub source_family: Option<String>,
    /// `text`, `embedding`, `image`, `video`, `audio`, `agent`...
    pub category: String,
    /// `alias`, `snapshot`, `listed_variant`, `managed_agent`...
    #[serde(default)]
    pub kind: Option<String>,
    pub verified: Verified,
    #[serde(default)]
    pub verified_on: Option<String>,
    #[serde(default)]
    pub notes: Vec<String>,
}

/// Fine-tuned models built on `base` (matched from `ft:<base>:...`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct FineTuneEntry {
    pub base: String,
    pub table: Table,
    pub recipe: String,
    pub status: EntryStatus,
    pub date: String,
    /// The base model the provider lists for these fine-tunes, if any.
    #[serde(default)]
    pub replacement_base: Option<String>,
    /// Whether `replacement_base` can itself be fine-tuned. Advice to
    /// retrain is given only when it can.
    #[serde(default)]
    pub fine_tunable: bool,
    /// Why the fine-tune cannot simply move (public wording).
    #[serde(default)]
    pub note: Option<String>,
}

/// What a parameter rule does when it applies.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RuleEffect {
    /// Add a parameter (`reasoning_effort="none"`).
    Add,
    /// Rename a parameter and add the parameters in `add`.
    Rename,
    /// The call needs a person: the change is not mechanical.
    Review,
    /// The parameters may stay, under `keep_*` conditions.
    Keep,
    /// Worth knowing; changes nothing.
    Note,
    /// A choice each repository makes (the recipe's `report_choice`): the
    /// call is reported with every option and changed by none until the
    /// repository picks one.
    Choice,
}

/// How firmly an option's effect is established.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum OptionStatus {
    /// A provider page states it, or a recorded live call shows it.
    Confirmed,
    /// Neither does yet.
    Unverified,
}

/// One option of a [`RuleEffect::Choice`] rule.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ChoiceOption {
    /// `reasoning_none`, `model_default`.
    pub id: String,
    /// For people: `keep reasoning off`.
    pub label: String,
    #[serde(default)]
    pub add: Vec<AddParam>,
    /// Parameters the option removes (when the call passes them).
    #[serde(default)]
    pub remove: Vec<String>,
    /// Parameters the option keeps (when the call passes them).
    #[serde(default)]
    pub keep: Vec<String>,
    /// What changes for the call: behaviour and cost.
    pub effect: String,
    pub status: OptionStatus,
}

/// A parameter to add, for one endpoint (`*` for any).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AddParam {
    pub endpoint: String,
    pub name: String,
    pub value: serde_json::Value,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RenameParam {
    pub from: String,
    pub to: String,
}

/// A parameter rule that can be checked from a call's keyword-argument names.
/// Every non-empty condition must hold.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ParamRule {
    pub id: String,
    pub rule_set: String,
    pub effect: RuleEffect,
    /// `chat.completions`, `responses`, `completions_legacy`, `assistants`.
    #[serde(default)]
    pub endpoints: Vec<String>,
    /// Client routings (`google_generativeai_legacy`).
    #[serde(default)]
    pub routings: Vec<String>,
    #[serde(default)]
    pub source_families: Vec<String>,
    /// Replacement models the rule is about.
    #[serde(default)]
    pub targets: Vec<String>,
    /// Retiring models the rule is about.
    #[serde(default)]
    pub source_models: Vec<String>,
    /// At least one of these keyword arguments is passed.
    #[serde(default)]
    pub any_kwargs: Vec<String>,
    /// All of these are passed.
    #[serde(default)]
    pub all_kwargs: Vec<String>,
    /// None of these is passed.
    #[serde(default)]
    pub lacks_kwargs: Vec<String>,
    #[serde(default)]
    pub add: Vec<AddParam>,
    #[serde(default)]
    pub rename: Option<RenameParam>,
    /// For `keep`: the targets the parameters were verified on.
    #[serde(default)]
    pub keep_targets: Vec<String>,
    /// For `keep`: verified only at reasoning effort `none`.
    #[serde(default)]
    pub keep_needs_effort_none: bool,
    /// For [`RuleEffect::Choice`]: the choice this rule belongs to. The
    /// rule whose `choice` is its own id is the choice's anchor.
    #[serde(default)]
    pub choice: Option<String>,
    /// For [`RuleEffect::Choice`]: the options, in the anchor's order.
    #[serde(default)]
    pub options: Vec<ChoiceOption>,
    /// An automatic change whose effect depends on a choice.
    #[serde(default)]
    pub see_choice: Option<String>,
    /// What the choice means for this change (with `see_choice`).
    #[serde(default)]
    pub choice_note: Option<String>,
    /// For people; `{target}` is the replacement model.
    pub message: String,
    /// When the rule's change cannot be made at this call.
    #[serde(default)]
    pub else_message: Option<String>,
    pub verified: Verified,
    #[serde(default)]
    pub verified_on: Option<String>,
    /// For a live rule: the models the live calls used. The live label holds
    /// only for these targets.
    #[serde(default)]
    pub live_models: Vec<String>,
    /// For a live rule: the APIs the live calls used (`chat.completions`).
    #[serde(default)]
    pub live_endpoints: Vec<String>,
    /// For a live rule: the label where the live calls did not reach (another
    /// target or another API): `docs` or `unverified`.
    #[serde(default)]
    pub otherwise_verified: Option<Verified>,
    #[serde(default)]
    pub source_url: Option<String>,
}

/// A recipe rule the engine does not evaluate, and why.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SkippedRule {
    pub id: String,
    pub rule_set: String,
    pub reason: String,
}

/// The whole data file.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RetirementData {
    pub schema: u32,
    /// The oldest date any recipe's pages were read; each recipe keeps its
    /// own `retrieved_on`.
    pub data_as_of: String,
    pub generated_at: String,
    pub generator: String,
    /// Where the recipes came from (`repository@commit:path`). The recipes
    /// are in a private repository; every fact also names its provider page.
    pub source: String,
    /// FNV-1a 64 of the canonical JSON of every key except `digest` and
    /// `generated_at`.
    pub digest: String,
    pub recipes: Vec<RecipeInfo>,
    pub entries: Vec<ModelEntry>,
    pub fine_tunes: Vec<FineTuneEntry>,
    pub rules: Vec<ParamRule>,
    pub skipped_rules: Vec<SkippedRule>,
}

/// The bundled data with lookup indexes.
#[derive(Debug)]
pub struct Retirements {
    pub data: RetirementData,
    pub as_of: Date,
    by_model: HashMap<(Table, String), usize>,
    by_fine_tune: HashMap<(Table, String), usize>,
    recipes: HashMap<String, usize>,
    rules_by_set: HashMap<String, Vec<usize>>,
}

impl Retirements {
    /// Parses and indexes a data file.
    pub fn from_json(json: &str) -> Result<Retirements, String> {
        let data: RetirementData = serde_json::from_str(json)
            .map_err(|e| format!("model retirement data is not valid: {e}"))?;
        if data.schema != DATA_SCHEMA {
            return Err(format!(
                "model retirement data has schema {}, this build reads {DATA_SCHEMA}",
                data.schema
            ));
        }
        let as_of = Date::parse(&data.data_as_of)
            .ok_or_else(|| format!("bad data_as_of {}", data.data_as_of))?;
        let mut by_model = HashMap::new();
        for (index, entry) in data.entries.iter().enumerate() {
            if by_model
                .insert((entry.table, entry.model.clone()), index)
                .is_some()
            {
                return Err(format!(
                    "{} is listed twice for {}",
                    entry.model, entry.table
                ));
            }
        }
        let by_fine_tune = data
            .fine_tunes
            .iter()
            .enumerate()
            .map(|(index, f)| ((f.table, f.base.clone()), index))
            .collect();
        let recipes = data
            .recipes
            .iter()
            .enumerate()
            .map(|(index, r)| (r.id.clone(), index))
            .collect();
        let mut rules_by_set: HashMap<String, Vec<usize>> = HashMap::new();
        for (index, rule) in data.rules.iter().enumerate() {
            rules_by_set
                .entry(rule.rule_set.clone())
                .or_default()
                .push(index);
        }
        Ok(Retirements {
            data,
            as_of,
            by_model,
            by_fine_tune,
            recipes,
            rules_by_set,
        })
    }

    /// The entry for `model` on `table`, matched exactly.
    pub fn entry(&self, table: Table, model: &str) -> Option<&ModelEntry> {
        self.by_model
            .get(&(table, model.to_string()))
            .map(|&i| &self.data.entries[i])
    }

    /// Fine-tunes of `base` on `table`.
    pub fn fine_tune(&self, table: Table, base: &str) -> Option<&FineTuneEntry> {
        self.by_fine_tune
            .get(&(table, base.to_string()))
            .map(|&i| &self.data.fine_tunes[i])
    }

    pub fn recipe(&self, id: &str) -> Option<&RecipeInfo> {
        self.recipes.get(id).map(|&i| &self.data.recipes[i])
    }

    /// The parameter rules of a rule set, in data order.
    pub fn rules(&self, rule_set: &str) -> impl Iterator<Item = &ParamRule> {
        self.rules_by_set
            .get(rule_set)
            .into_iter()
            .flatten()
            .map(move |&i| &self.data.rules[i])
    }
}

/// The bundled data, parsed once.
pub fn bundled() -> Result<&'static Retirements, String> {
    static DATA: OnceLock<Result<Retirements, String>> = OnceLock::new();
    DATA.get_or_init(|| Retirements::from_json(DATA_JSON))
        .as_ref()
        .map_err(Clone::clone)
}

/// Keys the digest leaves out: the digest itself, and the day the file was
/// written.
const UNDIGESTED: [&str; 2] = ["digest", "generated_at"];

/// FNV-1a 64 over the canonical JSON (sorted keys, no whitespace) of every
/// key except [`UNDIGESTED`], as `fnv1a64:<hex>`. The generator computes the
/// same.
pub fn content_digest(json: &str) -> Result<String, String> {
    let value: serde_json::Value = serde_json::from_str(json).map_err(|e| e.to_string())?;
    let object = value
        .as_object()
        .ok_or_else(|| "the data is not a JSON object".to_string())?;
    let mut body = serde_json::Map::new();
    for (key, item) in object {
        if !UNDIGESTED.contains(&key.as_str()) {
            body.insert(key.clone(), item.clone());
        }
    }
    let mut canonical = String::new();
    write_canonical(&serde_json::Value::Object(body), &mut canonical);
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in canonical.bytes() {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    Ok(format!("fnv1a64:{hash:016x}"))
}

fn write_canonical(value: &serde_json::Value, out: &mut String) {
    match value {
        serde_json::Value::Object(map) => {
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            out.push('{');
            for (i, key) in keys.into_iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(&serde_json::Value::String(key.clone()).to_string());
                out.push(':');
                write_canonical(&map[key], out);
            }
            out.push('}');
        }
        serde_json::Value::Array(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_canonical(item, out);
            }
            out.push(']');
        }
        other => out.push_str(&other.to_string()),
    }
}

#[cfg(test)]
mod data_tests {
    //! The bundled file must be exactly what the generator writes. These run
    //! on every `cargo test`, so a hand edit or a half-applied regeneration
    //! fails CI; `--check` in the generator catches recipes that moved on.

    use super::*;
    use std::collections::HashSet;

    fn data() -> &'static Retirements {
        bundled().expect("bundled data parses")
    }

    #[test]
    fn digest_matches_the_generator() {
        let digest = content_digest(DATA_JSON).unwrap();
        assert_eq!(
            digest,
            data().data.digest,
            "data/model-retirements.json was edited by hand: regenerate it with \
             scripts/retirements/generate_model_retirements.py"
        );
    }

    #[test]
    fn digest_notices_a_one_character_edit() {
        let edited = DATA_JSON.replacen("\"2027-01-14\"", "\"2027-01-15\"", 1);
        assert_ne!(edited, DATA_JSON);
        assert_ne!(content_digest(&edited).unwrap(), data().data.digest);
    }

    #[test]
    fn digest_covers_provenance_but_not_the_write_date() {
        let original = &data().data.digest;
        let edit = |key: &str, value: serde_json::Value| {
            let mut json: serde_json::Value = serde_json::from_str(DATA_JSON).unwrap();
            json[key] = value;
            content_digest(&json.to_string()).unwrap()
        };
        // Hand edits to the dates, the source, the recipe hashes or the
        // skipped rules all change the digest.
        assert_ne!(&edit("data_as_of", "2026-12-31".into()), original);
        assert_ne!(&edit("source", "someone@else:recipes/".into()), original);
        let mut recipes = serde_json::to_value(&data().data.recipes).unwrap();
        recipes[0]["sha256"] = "0".repeat(64).into();
        assert_ne!(&edit("recipes", recipes), original);
        assert_ne!(&edit("skipped_rules", serde_json::json!([])), original);
        // The day the file was written is not content.
        assert_eq!(&edit("generated_at", "2030-01-01".into()), original);
    }

    #[test]
    fn provenance_is_recorded() {
        let d = &data().data;
        assert_eq!(d.schema, DATA_SCHEMA);
        assert!(Date::parse(&d.generated_at).is_some());
        assert!(data().as_of <= Date::parse(&d.generated_at).unwrap());
        // The data date is the oldest page date, never a newer one.
        let oldest = d
            .recipes
            .iter()
            .map(|r| Date::parse(&r.retrieved_on).unwrap())
            .min()
            .unwrap();
        assert_eq!(data().as_of, oldest);
        assert!(
            d.source.contains('@'),
            "source names a commit: {}",
            d.source
        );
        assert!(d.generator.ends_with(".py"));
        let tables: HashSet<Table> = d.recipes.iter().map(|r| r.table).collect();
        assert_eq!(
            tables.len(),
            Table::ALL.len(),
            "every provider has a recipe"
        );
        for recipe in &d.recipes {
            assert!(!recipe.version.is_empty(), "{}", recipe.id);
            assert_eq!(recipe.sha256.len(), 64, "{}", recipe.id);
            assert!(Date::parse(&recipe.retrieved_on).is_some(), "{}", recipe.id);
            assert!(!recipe.source_urls.is_empty(), "{}", recipe.id);
            for url in &recipe.source_urls {
                assert!(url.starts_with("https://"), "{url}");
            }
        }
    }

    #[test]
    fn entries_are_consistent() {
        let r = data();
        for entry in &r.data.entries {
            let what = format!("{} ({})", entry.model, entry.table);
            assert!(r.recipe(&entry.recipe).is_some(), "{what}: unknown recipe");
            assert_eq!(
                r.recipe(&entry.recipe).unwrap().table,
                entry.table,
                "{what}"
            );
            if let Some(date) = &entry.date {
                assert!(Date::parse(date).is_some(), "{what}: bad date {date}");
            }
            if entry.status == EntryStatus::Retiring {
                assert!(entry.date.is_some(), "{what}: retiring without a date");
            }
            assert_ne!(
                entry.replacement.as_deref(),
                Some(entry.model.as_str()),
                "{what}"
            );
            if entry.action == Action::Rewrite {
                assert!(
                    entry.replacement.is_some(),
                    "{what}: rewrite needs a replacement"
                );
            }
            if let Some(set) = &entry.rule_set {
                assert!(r.recipe(set).is_some(), "{what}: unknown rule set {set}");
            }
            if entry.verified == Verified::Live {
                assert!(
                    entry.verified_on.as_deref().and_then(Date::parse).is_some(),
                    "{what}"
                );
            }
            assert!(
                !entry.model.is_empty() && !entry.model.chars().any(char::is_whitespace),
                "{what}"
            );
        }
        for fine in &r.data.fine_tunes {
            assert!(Date::parse(&fine.date).is_some(), "{}", fine.base);
            assert!(r.recipe(&fine.recipe).is_some(), "{}", fine.base);
        }
    }

    #[test]
    fn rules_point_at_real_models() {
        let r = data();
        for rule in &r.data.rules {
            let entries: Vec<&ModelEntry> = r
                .data
                .entries
                .iter()
                .filter(|e| e.rule_set.as_deref() == Some(rule.rule_set.as_str()))
                .collect();
            assert!(!entries.is_empty(), "{}: empty rule set", rule.id);
            let replacements: HashSet<&str> = entries
                .iter()
                .filter_map(|e| e.replacement.as_deref())
                .collect();
            for target in rule.targets.iter().chain(&rule.keep_targets) {
                assert!(
                    replacements.contains(target.as_str()),
                    "{}: target {target} is no replacement in {}",
                    rule.id,
                    rule.rule_set
                );
            }
            for model in &rule.source_models {
                assert!(
                    entries.iter().any(|e| &e.model == model),
                    "{}: {model} is not in {}",
                    rule.id,
                    rule.rule_set
                );
            }
            assert!(!rule.message.trim().is_empty(), "{}", rule.id);
            match rule.effect {
                RuleEffect::Add => assert!(!rule.add.is_empty(), "{}", rule.id),
                RuleEffect::Rename => assert!(rule.rename.is_some(), "{}", rule.id),
                _ => {}
            }
            if rule.verified == Verified::Live {
                assert!(
                    rule.verified_on.as_deref().and_then(Date::parse).is_some(),
                    "{}",
                    rule.id
                );
                // A live label names what the live calls covered.
                assert!(!rule.live_models.is_empty(), "{}", rule.id);
                assert_eq!(rule.live_endpoints, ["chat.completions"], "{}", rule.id);
                assert!(rule.otherwise_verified.is_some(), "{}", rule.id);
                assert_ne!(rule.otherwise_verified, Some(Verified::Live), "{}", rule.id);
            }
        }
    }

    #[test]
    fn choices_offer_their_anchors_options() {
        let r = data();
        let mut anchors = 0;
        for rule in &r.data.rules {
            if let Some(choice) = &rule.choice {
                assert_eq!(rule.effect, RuleEffect::Choice, "{}", rule.id);
                let anchor = r
                    .rules(&rule.rule_set)
                    .find(|a| &a.id == choice && a.choice.as_deref() == Some(choice))
                    .unwrap_or_else(|| panic!("{}: no anchor {choice}", rule.id));
                anchors += usize::from(anchor.id == rule.id);
                let ids = |rule: &ParamRule| -> Vec<String> {
                    rule.options.iter().map(|o| o.id.clone()).collect()
                };
                assert!(rule.options.len() >= 2, "{}", rule.id);
                assert_eq!(ids(rule), ids(anchor), "{}", rule.id);
                for option in &rule.options {
                    assert!(!option.label.is_empty() && !option.effect.is_empty());
                }
            } else {
                assert_ne!(rule.effect, RuleEffect::Choice, "{}", rule.id);
                assert!(rule.options.is_empty(), "{}", rule.id);
            }
            if let Some(choice) = &rule.see_choice {
                assert!(rule.choice_note.is_some(), "{}", rule.id);
                assert!(
                    r.rules(&rule.rule_set).any(|a| &a.id == choice),
                    "{}: see_choice {choice}",
                    rule.id
                );
            }
        }
        // One reasoning choice per OpenAI dated recipe, and Claude's thinking.
        assert_eq!(anchors, 3);
    }

    #[test]
    fn no_automatic_change_sets_the_reasoning_effort() {
        // The founder's 18 Oct decision: the reasoning effort is asked per
        // repository; the lead's 20 Oct decision does the same for Claude's
        // thinking. Only a choice's options may name them.
        for rule in &data().data.rules {
            if !matches!(
                rule.effect,
                RuleEffect::Add | RuleEffect::Rename | RuleEffect::Keep
            ) {
                continue;
            }
            for add in &rule.add {
                let named = add.name.contains("effort")
                    || add.name == "thinking"
                    || (add.name == "reasoning" && add.value.get("effort").is_some());
                assert!(!named, "{} sets {} automatically", rule.id, add.name);
            }
            if let Some(rename) = &rule.rename {
                assert_ne!(rename.to, "thinking", "{}", rule.id);
            }
        }
        for id in ["ANT-THINKING-DEFAULT", "ANT-THINKING-DISABLED"] {
            let rule = data().data.rules.iter().find(|r| r.id == id).expect(id);
            assert_eq!(rule.effect, RuleEffect::Choice, "{id}");
            assert_eq!(rule.choice.as_deref(), Some("ANT-THINKING-DEFAULT"), "{id}");
        }
        for id in [
            "OAI-REASONING-DEFAULT",
            "OAI-TOOLS-CC",
            "OAI-LEGACY-FUNCTIONS",
            "OAI-SAMPLING",
            "G6-REASONING-DEFAULT",
            "G6-TOOLS-CC",
            "G6-LEGACY-FUNCTIONS",
            "G6-SAMPLING",
        ] {
            let rule = data().data.rules.iter().find(|r| r.id == id).expect(id);
            assert_eq!(rule.effect, RuleEffect::Choice, "{id}");
        }
    }

    #[test]
    fn fine_tunes_name_a_base_only_when_it_can_be_fine_tuned() {
        let r = data();
        for fine in &r.data.fine_tunes {
            assert!(fine.note.is_some(), "{}", fine.base);
            assert!(
                !fine.fine_tunable,
                "{}: no listed base supports fine-tuning today",
                fine.base
            );
        }
        // gpt-6-luna does not support fine-tuning: no base is listed.
        let mini = r
            .fine_tune(Table::Openai, "gpt-4o-mini-2024-07-18")
            .expect("fine-tunes of the gpt-4o mini snapshot are matched");
        assert_eq!(mini.replacement_base, None);
        assert_eq!(mini.date, "2027-01-14");
    }

    #[test]
    fn launch_facts_are_in_the_data() {
        // The soft-launch check leans on these; if a regeneration drops one,
        // the README and the launch copy are wrong.
        let r = data();
        for alias in ["gpt-4o", "gpt-4o-mini", "gpt-4.1", "gpt-4.1-mini"] {
            let entry = r.entry(Table::Openai, alias).expect(alias);
            assert_eq!(entry.status, EntryStatus::Retiring);
            assert_eq!(entry.date.as_deref(), Some("2027-01-14"));
            assert_eq!(entry.replacement.as_deref(), Some("gpt-6-luna"));
        }
        let sonnet = r
            .entry(Table::Anthropic, "claude-3-5-sonnet-20241022")
            .unwrap();
        assert_eq!(sonnet.status, EntryStatus::ShutDown);
        assert!(r
            .entry(Table::Openai, "claude-3-5-sonnet-20241022")
            .is_none());
        assert!(r.entry(Table::Openai, "gpt-6-luna").is_none());
        let max_tokens = r
            .rules("openai-2027-01-14")
            .find(|rule| rule.id == "G6-MAX-TOKENS")
            .unwrap();
        assert_eq!(max_tokens.verified, Verified::Live);
        assert_eq!(
            max_tokens.rename,
            Some(RenameParam {
                from: "max_tokens".into(),
                to: "max_completion_tokens".into()
            })
        );
        // The rename stays automatic and adds nothing; the reasoning effort
        // is the per-repo choice it points to.
        assert!(max_tokens.add.is_empty());
        assert_eq!(
            max_tokens.see_choice.as_deref(),
            Some("G6-REASONING-DEFAULT")
        );
    }

    #[test]
    fn rejects_unknown_fields_and_schemas() {
        let mut value: serde_json::Value = serde_json::from_str(DATA_JSON).unwrap();
        value["entries"][0]["surprise"] = serde_json::json!(true);
        assert!(Retirements::from_json(&value.to_string()).is_err());
        let mut value: serde_json::Value = serde_json::from_str(DATA_JSON).unwrap();
        value["schema"] = serde_json::json!(99);
        assert!(Retirements::from_json(&value.to_string())
            .unwrap_err()
            .contains("schema"));
    }
}
